{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2174-11-30 20:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand you've been having nausea, vomiting, and diarrhea. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2174-11-30 20:16:30",
      "speaker": "Patient",
      "text": "Yes, thank you. The vomiting started last night, and the diarrhea began about three days ago. I’ve had pain around my G-tube site too."
    },
    {
      "turn_number": 3,
      "time": "2174-11-30 20:17:45",
      "speaker": "Doctor",
      "text": "I see. You mentioned your G-tube was recently changed and the balloon was upsized. Did the pain get worse after that?"
    },
    {
      "turn_number": 4,
      "time": "2174-11-30 20:18:30",
      "speaker": "Patient",
      "text": "Exactly. Right after the change, the pain increased. And when I restarted tube feeds last weekend, the diarrhea started."
    },
    {
      "turn_number": 5,
      "time": "2174-11-30 20:19:15",
      "speaker": "Doctor",
      "text": "That makes sense. You stopped the tube feeds when the symptoms got worse?"
    },
    {
      "turn_number": 6,
      "time": "2174-11-30 20:20:00",
      "speaker": "Patient",
      "text": "Yes, I stopped them the night before last. I just couldn’t keep anything down, even by mouth."
    },
    {
      "turn_number": 7,
      "time": "2174-11-30 20:21:00",
      "speaker": "Doctor",
      "text": "Okay. You’ve had similar episodes before, including norovirus. Any blood in your vomit or stool this time?"
    },
    {
      "turn_number": 8,
      "time": "2174-11-30 20:21:45",
      "speaker": "Patient",
      "text": "No, no blood. Just clear vomit and loose stools."
    },
    {
      "turn_number": 9,
      "time": "2174-11-30 20:22:30",
      "speaker": "Doctor",
      "text": "Good to know. We’ll start you on IV fluids to rehydrate you and keep you on bowel rest for now—no food or tube feeds."
    },
    {
      "turn_number": 10,
      "time": "2174-11-30 20:23:15",
      "speaker": "Patient",
      "text": "Will I be able to eat soon?"
    },
    {
      "turn_number": 11,
      "time": "2174-11-30 20:24:00",
      "speaker": "Doctor",
      "text": "We’ll wait and see how you do. Once the nausea settles, we’ll try clear liquids and go from there. We don’t want to rush it."
    },
    {
      "turn_number": 12,
      "time": "2174-11-30 20:25:00",
      "speaker": "Patient",
      "text": "That’s fair. My anxiety’s been worse with all this. It’s hard not knowing what’s wrong."
    },
    {
      "turn_number": 13,
      "time": "2174-11-30 20:26:00",
      "speaker": "Doctor",
      "text": "I understand. We’ve asked Psychiatry to see you to help manage the anxiety during your stay."
    },
    {
      "turn_number": 14,
      "time": "2174-11-30 20:27:00",
      "speaker": "Patient",
      "text": "Thank you. I’ve been on lorazepam and fluoxetine—should I keep taking those?"
    },
    {
      "turn_number": 15,
      "time": "2174-11-30 20:28:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll continue your regular meds unless there’s a reason to adjust. We’ll review them carefully."
    },
    {
      "turn_number": 16,
      "time": "2174-12-01 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs from yesterday show your white count was low at first but came up today—looks like no active infection."
    },
    {
      "turn_number": 17,
      "time": "2174-12-01 08:31:30",
      "speaker": "Patient",
      "text": "That’s good, right? No infection?"
    },
    {
      "turn_number": 18,
      "time": "2174-12-01 08:32:45",
      "speaker": "Doctor",
      "text": "Yes, that’s reassuring. Your liver enzymes were slightly elevated but stable. Nothing suggests pancreatitis—lipase was normal."
    },
    {
      "turn_number": 19,
      "time": "2174-12-01 08:34:00",
      "speaker": "Patient",
      "text": "I’ve been feeling a little better overnight. Nausea’s not as bad."
    },
    {
      "turn_number": 20,
      "time": "2174-12-01 08:35:15",
      "speaker": "Doctor",
      "text": "That’s great. We’ll try advancing your diet today—start with clear liquids and see how you tolerate it."
    },
    {
      "turn_number": 21,
      "time": "2174-12-01 08:36:30",
      "speaker": "Patient",
      "text": "Can I have water and broth?"
    },
    {
      "turn_number": 22,
      "time": "2174-12-01 08:37:15",
      "speaker": "Doctor",
      "text": "Yes, exactly. Small sips at first. We’ll monitor you closely. If no vomiting in a few hours, we’ll move to full liquids."
    },
    {
      "turn_number": 23,
      "time": "2174-12-01 14:00:00",
      "speaker": "Doctor",
      "text": "You’ve done well with clear liquids. How’s your stomach feeling?"
    },
    {
      "turn_number": 24,
      "time": "2174-12-01 14:01:15",
      "speaker": "Patient",
      "text": "Much better. I had some apple juice and broth and didn’t vomit."
    },
    {
      "turn_number": 25,
      "time": "2174-12-01 14:02:30",
      "speaker": "Doctor",
      "text": "Excellent. We’ll try a soft diet now—things like mashed potatoes and applesauce. Still no tube feeds for now."
    },
    {
      "turn_number": 26,
      "time": "2174-12-01 14:03:45",
      "speaker": "Patient",
      "text": "Okay. When might I be able to restart tube feeds at home?"
    },
    {
      "turn_number": 27,
      "time": "2174-12-01 14:05:00",
      "speaker": "Doctor",
      "text": "We’ll discuss that before discharge. For now, let’s focus on oral intake. Your body needs time to settle."
    },
    {
      "turn_number": 28,
      "time": "2174-12-02 09:00:00",
      "speaker": "Doctor",
      "text": "You tolerated the soft diet well yesterday. Today, we’ll try a regular diet."
    },
    {
      "turn_number": 29,
      "time": "2174-12-02 09:01:15",
      "speaker": "Patient",
      "text": "Really? That’s great. I’m hungry!"
    },
    {
      "turn_number": 30,
      "time": "2174-12-02 09:02:30",
      "speaker": "Doctor",
      "text": "Yes, but start slow. We’ll bring a small meal. If you do well, you can have more."
    },
    {
      "turn_number": 31,
      "time": "2174-12-02 13:30:00",
      "speaker": "Doctor",
      "text": "You’ve done well with the regular diet. No nausea or vomiting?"
    },
    {
      "turn_number": 32,
      "time": "2174-12-02 13:31:15",
      "speaker": "Patient",
      "text": "None at all. The diarrhea’s improved too."
    },
    {
      "turn_number": 33,
      "time": "2174-12-02 13:32:30",
      "speaker": "Doctor",
      "text": "That’s excellent progress. We’ll keep you on your usual medications, including pantoprazole and sucralfate for stomach protection."
    },
    {
      "turn_number": 34,
      "time": "2174-12-02 13:34:00",
      "speaker": "Patient",
      "text": "I’ve been taking ranitidine at night too. Should I keep doing that?"
    },
    {
      "turn_number": 35,
      "time": "2174-12-02 13:35:15",
      "speaker": "Doctor",
      "text": "Yes, we’ll continue that as well. It helps reduce stomach acid and may ease irritation."
    },
    {
      "turn_number": 36,
      "time": "2174-12-03 10:00:00",
      "speaker": "Doctor",
      "text": "Psychiatry saw you yesterday. They think your anxiety is contributing to your symptoms."
    },
    {
      "turn_number": 37,
      "time": "2174-12-03 10:01:30",
      "speaker": "Patient",
      "text": "I know it plays a role. They mentioned a clonidine patch?"
    },
    {
      "turn_number": 38,
      "time": "2174-12-03 10:02:45",
      "speaker": "Doctor",
      "text": "Yes, but we’re not using it here because your blood pressure has been on the lower side—systolic in the 80s to 90s."
    },
    {
      "turn_number": 39,
      "time": "2174-12-03 10:04:00",
      "speaker": "Patient",
      "text": "Oh, okay. I’ll talk to my outpatient psychiatrist about it."
    },
    {
      "turn_number": 40,
      "time": "2174-12-03 10:05:15",
      "speaker": "Doctor",
      "text": "Exactly. For now, we’ll keep using lorazepam as needed and continue your fluoxetine."
    },
    {
      "turn_number": 41,
      "time": "2174-12-04 09:00:00",
      "speaker": "Doctor",
      "text": "You’ve been doing so well—eating normally, no vomiting, pain is controlled. We’re thinking you could go home tomorrow."
    },
    {
      "turn_number": 42,
      "time": "2174-12-04 09:01:30",
      "speaker": "Patient",
      "text": "That’s great news! What should I watch for at home?"
    },
    {
      "turn_number": 43,
      "time": "2174-12-04 09:03:00",
      "speaker": "Doctor",
      "text": "Call or come back if you start vomiting again, can’t keep fluids down, or have signs of dehydration—like dizziness or dry mouth."
    },
    {
      "turn_number": 44,
      "time": "2174-12-04 09:04:30",
      "speaker": "Patient",
      "text": "What about the G-tube? When can I restart feeds?"
    },
    {
      "turn_number": 45,
      "time": "2174-12-04 09:06:00",
      "speaker": "Doctor",
      "text": "We recommend holding off for now. Follow up with your bariatric surgeon before restarting. They may want to assess the site."
    },
    {
      "turn_number": 46,
      "time": "2174-12-04 09:07:30",
      "speaker": "Patient",
      "text": "And my pain meds? I’ve been using oxycodone."
    },
    {
      "turn_number": 47,
      "time": "2174-12-04 09:08:45",
      "speaker": "Doctor",
      "text": "You’ll go home with a small prescription for oxycodone for breakthrough pain, but try to use it sparingly."
    },
    {
      "turn_number": 48,
      "time": "2174-12-04 09:10:00",
      "speaker": "Patient",
      "text": "I will. I don’t want to rely on it."
    },
    {
      "turn_number": 49,
      "time": "2174-12-05 08:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home today. You’re tolerating food, pain is mild, and you’re walking well."
    },
    {
      "turn_number": 50,
      "time": "2174-12-05 08:01:30",
      "speaker": "Patient",
      "text": "Thank you so much. I feel like I can manage now."
    },
    {
      "turn_number": 51,
      "time": "2174-12-05 08:03:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Keep taking your regular meds—pantoprazole, sucralfate, ranitidine, and your psychiatric medications."
    },
    {
      "turn_number": 52,
      "time": "2174-12-05 08:04:30",
      "speaker": "Patient",
      "text": "And the cholestyramine and bisacodyl?"
    },
    {
      "turn_number": 53,
      "time": "2174-12-05 08:05:45",
      "speaker": "Doctor",
      "text": "Yes, continue those as prescribed. They help with bowel control and cholesterol."
    },
    {
      "turn_number": 54,
      "time": "2174-12-05 08:07:00",
      "speaker": "Patient",
      "text": "I’ll follow up with my doctors. Any restrictions?"
    },
    {
      "turn_number": 55,
      "time": "2174-12-05 08:08:15",
      "speaker": "Doctor",
      "text": "Rest for a few days, stay hydrated, and avoid heavy lifting until you see your surgeon. And no driving while on pain meds."
    },
    {
      "turn_number": 56,
      "time": "2174-12-05 08:09:30",
      "speaker": "Patient",
      "text": "Got it. I’ll take it easy."
    },
    {
      "turn_number": 57,
      "time": "2174-12-05 08:10:45",
      "speaker": "Doctor",
      "text": "We’ll send discharge instructions with all this. If anything changes, don’t hesitate to call or come back."
    },
    {
      "turn_number": 58,
      "time": "2174-12-05 08:12:00",
      "speaker": "Patient",
      "text": "I really appreciate all the care. I was so worried."
    },
    {
      "turn_number": 59,
      "time": "2174-12-05 08:13:15",
      "speaker": "Doctor",
      "text": "You did great. Keep in touch with your team, and take care of yourself."
    },
    {
      "turn_number": 60,
      "time": "2174-12-05 08:14:30",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    }
  ],
  "summary": {
    "admission_start": "2174-11-30 19:58:00",
    "admission_end": "2174-12-05 15:06:00",
    "summary_paragraph": "The patient was admitted with nausea, vomiting, diarrhea, and abdominal pain centered at the G-tube site, symptoms that began after restarting tube feeds and changing the G-tube balloon. She was placed on bowel rest and received IV fluids. Over the course of five days, her symptoms improved, and she successfully advanced from clear liquids to a regular diet without complications. Her pain was managed with IV morphine initially, then transitioned to oral oxycodone. Psychiatry consulted for anxiety management but recommended against a clonidine patch due to low blood pressure. The patient was discharged home in stable condition, tolerating oral intake, with instructions to follow up with her bariatric surgeon before restarting tube feeds and to monitor for signs of dehydration or symptom recurrence.",
    "problems": [
      "Nausea with vomiting, unspecified",
      "Gastrostomy status",
      "Major depressive disorder, single episode, unspecified",
      "Diarrhea, unspecified",
      "Unspecified abdominal pain",
      "Bariatric surgery status",
      "Gastro-esophageal reflux disease without esophagitis",
      "Personal history of Methicillin resistant Staphylococcus aureus infection",
      "Post-traumatic stress disorder, unspecified",
      "Obesity, unspecified",
      "Body mass index [BMI] 33.0-33.9, adult"
    ]
  }
}
